import torch, b200probe
src = r'''
extern "C" __global__ void __launch_bounds__(1024,1) wr_rd(float4* ws, float4* rdbase, unsigned long long per, int hint, int dowrite,
    unsigned* ctr, unsigned long long* st, float* sink) {
  unsigned long long t0,t1,t2;
  asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t0));
  float4* wb = ws + blockIdx.x*per;
  unsigned long long pol;
  if (hint==1) asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
  else if (hint==2) asm volatile("createpolicy.fractional.L2::evict_first.b64 %0, 1.0;" : "=l"(pol));
  else asm volatile("createpolicy.fractional.L2::evict_normal.b64 %0, 1.0;" : "=l"(pol));
  if (dowrite) {
    for (unsigned long long i = threadIdx.x; i < per; i += 1024) {
      float4 v = make_float4(i, 1.f, 2.f, 3.f);
      asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" :: "l"(wb+i), "f"(v.x),"f"(v.y),"f"(v.z),"f"(v.w), "l"(pol) : "memory");
    }
  }
  __syncthreads();
  if (threadIdx.x==0) { __threadfence(); atomicAdd(ctr,1u); while (atomicAdd(ctr,0u) < gridDim.x) {} }
  __syncthreads();
  asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t1));
  float4* rb = rdbase + blockIdx.x*per;
  float acc = 0.f;
  #pragma unroll 8
  for (unsigned long long i = threadIdx.x; i < per; i += 1024) {
    float4 v; asm volatile("ld.global.v4.f32 {%0,%1,%2,%3}, [%4];" : "=f"(v.x),"=f"(v.y),"=f"(v.z),"=f"(v.w) : "l"(rb+i));
    acc += v.x + v.w;
  }
  __syncthreads();
  asm volatile("mov.u64 %0, %%globaltimer;" : "=l"(t2));
  if (acc == -1.f) sink[0] = acc;
  if (threadIdx.x==0) { st[blockIdx.x*3]=t0; st[blockIdx.x*3+1]=t1; st[blockIdx.x*3+2]=t2; }
}
'''
k = b200probe.cuda_kernel(src, "wr_rd")
flush = torch.empty(2*126*1024*1024//4, device='cuda')
ws = torch.empty(2*80*1024*1024//4, device='cuda')
ctr = torch.zeros(1, dtype=torch.int32, device='cuda')
st = torch.zeros(148*3, dtype=torch.int64, device='cuda')
sink = torch.zeros(1, device='cuda')
import numpy as np
def run(mb, hint, dowrite, cold):
  per = (mb*1024*1024//16)//148
  res=[]
  for it in range(4):
    ctr.zero_(); flush.zero_()
    rd = ws[ws.numel()//2:] if cold else ws
    e0=torch.cuda.Event(enable_timing=True); e1=torch.cuda.Event(enable_timing=True)
    e0.record()
    k((148,),(1024,), ws.data_ptr(), rd.data_ptr(), np.uint64(per), np.int32(hint), np.int32(dowrite), ctr.data_ptr(), st.data_ptr(), sink.data_ptr())
    e1.record(); torch.cuda.synchronize()
    s = st.view(148,3).cpu().numpy()
    tw = (s[:,1].max()-s[:,0].min())/1e3; tr=(s[:,2].max()-s[:,1].min())/1e3
    res.append((tw,tr,e0.elapsed_time(e1)*1e3))
  r=np.array(res[1:]).mean(0)
  B = per*148*16
  print(f"{mb}MB hint={hint} write={dowrite} cold={cold}: write {r[0]:.1f}us ({B/r[0]/1e6:.2f}TB/s) read {r[1]:.1f}us ({B/r[1]/1e6:.2f}TB/s) total {r[2]:.1f}us")
for mb in (38,76):
  run(mb,1,1,0); run(mb,0,1,0); run(mb,1,1,1); run(mb,0,0,0)

