constexpr int OFF_B1 = OFF_W + NST * 32768;
constexpr int OFF_GW = OFF_B1 + 2048;
constexpr int OFF_SC = OFF_GW + 2048;  // GRN scale [2 batch slots][512]
constexpr int OFF_B2P = OFF_SC + 4096;
constexpr int OFF_RED = OFF_B2P + 512;
