  asm volatile("st.global.L2::cache_hint.v4.f32 [%0], {%1,%2,%3,%4}, %5;" ::"l"(q), "f"(a), "f"(b), "f"(c), "f"(d), "l"(pol) : "memory");
}
__device__ __forceinline__ uint32_t h2u(__half2 h) { return *reinterpret_cast<uint32_t*>(&h); }
__device__ __forceinline__ void split2(float a, float b, uint32_t& hi, uint32_t& lo) {  // fp16 hi + fp16 lo of a pair
  const __half2 h = __floats2half2_rn(a, b);
  const float2 f = __half22float2(h);
  hi = h2u(h);
  lo = h2u(__floats2half2_rn(a - f.x, b - f.y));
}
__device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
__device__ __forceinline__ uint64_t f2pack(float a, float b) { uint64_t r; asm("mov.b64 %0, {%1, %2};" : "=l"(r) : "f"(a), "f"(b)); return r; }
__device__ __forceinline__ void f2unpack(uint64_t r, float& a, float& b) { asm("mov.b64 {%0, %1}, %2;" : "=f"(a), "=f"(b) : "l"(r)); }
__device__ __forceinline__ uint64_t fma2(uint64_t a, uint64_t b, uint64_t c) { uint64_t d; asm("fma.rn.f32x2 %0, %1, %2, %3;" : "=l"(d) : "l"(a), "l"(b), "l"(c)); return d; }
__device__ __forceinline__ uint64_t mul2(uint64_t a, uint64_t b) { uint64_t d; asm("mul.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
__device__ __forceinline__ uint64_t add2(uint64_t a, uint64_t b) { uint64_t d; asm("add.rn.f32x2 %0, %1, %2;" : "=l"(d) : "l"(a), "l"(b)); return d; }
// exact-class GELU on a pair: Abramowitz-Stegun 7.1.26 erfc (|err| <= 1.5e-7), hc = 0.5 erfc(|x| / sqrt2),
// h = x hc + max(x - 2 x hc, 0); ss += h^2
__device__ __forceinline__ void gelu2(float& x0, float& x1, uint64_t& ss2) {
  float t0, t1, e0, e1, q0, q1, d0, d1;
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t0) : "f"(fmaf(fabsf(x0), 0.231641900f, 1.f)));
  asm("rcp.approx.ftz.f32 %0, %1;" : "=f"(t1) : "f"(fmaf(fabsf(x1), 0.231641900f, 1.f)));
  const uint64_t T = f2pack(t0, t1), X = f2pack(x0, x1);
  uint64_t P = fma2(T, f2pack(0.5307027145f, 0.5307027145f), f2pack(-0.7265760135f, -0.7265760135f));
  P = fma2(T, P, f2pack(0.7107068705f, 0.7107068705f));
  P = fma2(T, P, f2pack(-0.142248368f, -0.142248368f));
  P = fma2(T, P, f2pack(0.127414796f, 0.127414796f));
  P = mul2(P, T);
  f2unpack(mul2(X, mul2(X, f2pack(-0.72134752044f, -0.72134752044f))), q0, q1);
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e0) : "f"(q0));
  asm("ex2.approx.ftz.f32 %0, %1;" : "=f"(e1) : "f"(q1));
  const uint64_t XH = mul2(X, mul2(P, f2pack(e0, e1)));
  f2unpack(fma2(XH, f2pack(-2.f, -2.f), X), d0, d1);
  const uint64_t H = add2(XH, f2pack(fmaxf(d0, 0.f), fmaxf(d1, 0.f)));
  ss2 = fma2(H, H, ss2);
  f2unpack(H, x0, x1);
}
// tile t: tokens [t0, t0 + nv); tokens < cb belong to batch b0, the rest to b0 + 1 (HW > 128: at most two batches)
__device__ __forceinline__ void tile_geom(int t, int N, int HW, int& t0, int& nv, int& b0, int& cb) {
  t0 = t * 128;
  nv = min(128, N - t0);
  b0 = t0 / HW;
  cb = min(nv, (b0 + 1) * HW - t0);
}
}  // namespace

#define BAR(i) (bar + 8u * (uint32_t)(i))
#define FULL(s) BAR(s)
#define EMPTY(s) BAR(4 + (s))
#define XFULL BAR(8)
#define XFREE BAR(9)
#define G1FULL(b) BAR(10 + (b))
#define TFREE(b) BAR(12 + (b))
#define HFULL(b) BAR(14 + (b))
#define HFREE(b) BAR(16 + (b))
#define G2DONE BAR(18)
#define TFREE2 BAR(19)

__global__ void __launch_bounds__(NTH, 1) grn_mlp_kernel(const GParams p) {
  extern __shared__ unsigned char smraw[];
  unsigned char* sm = (unsigned char*)(((uintptr_t)smraw + 1023) & ~(uintptr_t)1023);
  const uint32_t sb = s_addr(sm);
  const int tid = threadIdx.x, warp = tid >> 5, lane = tid & 31;
  float* s_b1 = (float*)(sm + OFF_B1);
  float* s_gw = (float*)(sm + OFF_GW);
  float* s_sc = (float*)(sm + OFF_SC);
  float* s_b2p = (float*)(sm + OFF_B2P);
  float* s_red = (float*)(sm + OFF_RED);
  const uint32_t bar = sb + OFF_BAR;
  uint32_t* s_tmem = (uint32_t*)(sm + OFF_BAR + 160);
  const int G = (int)gridDim.x, cta = (int)blockIdx.x;
  const int R = (p.ntiles + G - 1) / G;

  if (tid == 0) {
    for (int i = 0; i < 20; i++) mbar_init(BAR(i), 1);
    asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
  }
  if (warp == NW) {
    asm volatile("tcgen05.alloc.cta_group::1.sync.aligned.shared::cta.b32 [%0], %1;" ::"r"(s_addr(s_tmem)), "r"(512) : "memory");
    asm volatile("tcgen05.relinquish_alloc_permit.cta_group::1.sync.aligned;" ::: "memory");
  }
  tc_before();
  __syncthreads();
  tc_after();
  const uint32_t tmem = *s_tmem;

  if (warp < NW) {
    // ---- phase 0: this CTA's slice of the fp16 hi/lo weight images (stage-ordered SW128 K-major A tiles), b2', gsum = 0
    {
      const int per = (32768 + G - 1) / G;
#pragma unroll 4
      for (int j = tid; j < per; j += 512) {
        const int f = cta * per + j;
        if (f >= 32768) break;
        float4 w;
        int stage, r, k0;
        if (f < 16384) {
          w = __ldg(reinterpret_cast<const float4*>(p.w1) + f);
          const int n = f >> 5;
          k0 = (f & 31) * 4;
          stage = (n >> 7) * 2 + (k0 >> 6);
          r = n & 127;
        } else {
          const int g = f - 16384;
          w = __ldg(reinterpret_cast<const float4*>(p.w2) + g);
          r = g >> 7;
          k0 = (g & 127) * 4;
          stage = 8 + (k0 >> 6);
        }
        const int kk = k0 & 63;
        unsigned char* dst = p.wimg + stage * 32768 + r * 128 + ((((kk >> 3) ^ (r & 7))) << 4) + (kk & 7) * 2;
        uint32_t h01, l01, h23, l23;
        split2(w.x, w.y, h01, l01);
        split2(w.z, w.w, h23, l23);
        *reinterpret_cast<uint2*>(dst) = make_uint2(h01, h23);
        *reinterpret_cast<uint2*>(dst + 16384) = make_uint2(l01, l23);
      }
      for (int c = cta * NW + warp; c < 128; c += G * NW) {
        const float4* wr = reinterpret_cast<const float4*>(p.w2 + c * 512);
        const float4* gr = reinterpret_cast<const float4*>(p.gb);
        float d = 0.f;
#pragma unroll
        for (int i = 0; i < 4; i++) {
          const float4 w = __ldg(wr + lane + 32 * i), g = __ldg(gr + lane + 32 * i);
          d = fmaf(w.x, g.x, fmaf(w.y, g.y, fmaf(w.z, g.z, fmaf(w.w, g.w, d))));
        }
        d = warp_sum(d);
        if (lane == 0) p.b2p[c] = p.b2[c] + d;
      }
      for (int i = cta * 512 + tid; i < p.B * 512; i += G * 512) p.gsum[i] = 0.f;
      s_b1[tid] = __ldg(p.b1 + tid);
      s_gw[tid] = __ldg(p.gw + tid);
      asm volatile("fence.proxy.async;" ::: "memory");
      wbar();
      if (tid == 0) {
        __threadfence();
        red_release(g_ctr, 1u);
        while (ld_acquire(g_ctr) < (unsigned)G) { }
      }
      wbar();
      if (tid < 128) s_b2p[tid] = __ldcg(p.b2p + tid);
    }
    uint64_t pol;
    asm volatile("createpolicy.fractional.L2::evict_last.b64 %0, 1.0;" : "=l"(pol));
    const int q4 = warp & 3, g4 = warp >> 2;
    int g1c = 0, g2c = 0;
    bool pend = false;  // a GEMM1 was issued whose X reads are not yet known complete
#pragma unroll 1
    for (int r = 0; r <= R; r++) {
      const int t1 = r * G + cta, t2 = (r - 1) * G + cta;
      const bool has1 = t1 < p.ntiles;
      const bool has2 = (r >= 1) && (t2 < p.ntiles);
      if (has1) {
        int t0, nv, b0, cb;
        tile_geom(t1, p.N, p.HW, t0, nv, b0, cb);
        if (pend) { mbar_wait(XFREE, (uint32_t)((g1c - 1) & 1)); pend = false; }
        // ---- x tile -> X^T hi/lo, MN-major SW128 (rows = channels, tokens contiguous); OOB tokens are zero
        float2 v[2][8];
#pragma unroll
        for (int it = 0; it < 2; it++) {
          const int task = tid + 512 * it, pp = task & 63, tg = task >> 6;
#pragma unroll
          for (int i = 0; i < 8; i++) {
            const int tk = tg * 8 + i;
            v[it][i] = (tk < nv) ? __ldg(reinterpret_cast<const float2*>(p.x + (size_t)(t0 + tk) * 128) + pp) : make_float2(0.f, 0.f);
          }
        }
#pragma unroll
        for (int it = 0; it < 2; it++) {
          const int task = tid + 512 * it, pp = task & 63, tg = task >> 6, nc = tg >> 3, uu = tg & 7;
#pragma unroll
          for (int cc = 0; cc < 2; cc++) {
            const int c = 2 * pp + cc;
            uint32_t hi[4], lo[4];
#pragma unroll
            for (int m = 0; m < 4; m++) {
              const float a = cc ? v[it][2 * m].y : v[it][2 * m].x;
              const float b = cc ? v[it][2 * m + 1].y : v[it][2 * m + 1].x;
              split2(a, b, hi[m], lo[m]);
            }
            unsigned char* d = sm + OFF_X + nc * 16384 + c * 128 + ((uu ^ (c & 7)) << 4);
            *reinterpret_cast<uint4*>(d) = make_uint4(hi[0], hi[1], hi[2], hi[3]);
            *reinterpret_cast<uint4*>(d + 32768) = make_uint4(lo[0], lo[1], lo[2], lo[3]);
          }
        }
        fence_proxy_async();
        wbar();
        if (tid == 0) mbar_arrive(XFULL);
        pend = true;
        g1c++;
        // ---- GEMM1 epilogue per 128-hidden block: + b1, GELU, sumsq per batch, fp32 h to the workspace (evict_last)
        float* hcur = p.hws + ((size_t)((r & 1) * G + cta) << 16);
#pragma unroll 1
        for (int hb = 0; hb < 4; hb++) {
          const int buf = hb & 1, use = 2 * (g1c - 1) + (hb >> 1);
          mbar_wait(G1FULL(buf), (uint32_t)(use & 1));
          tc_after();
          const int k = hb * 128 + 32 * q4 + lane;
          const float bk = s_b1[k];
          const uint64_t bk2 = f2pack(bk, bk);
          float s0 = 0.f, s1 = 0.f;
#pragma unroll
          for (int hf = 0; hf < 2; hf++) {
            const int c0 = 32 * g4 + 16 * hf;
            float a[16];
            tmem_ld16(tmem + ((uint32_t)(32 * q4) << 16) + (uint32_t)(buf * 128 + c0), a);
            uint64_t ss2 = f2pack(0.f, 0.f);
#pragma unroll
            for (int e = 0; e < 16; e += 2) {
              float x0, x1;
              f2unpack(add2(f2pack(a[e], a[e + 1]), bk2), x0, x1);
              gelu2(x0, x1, ss2);
              a[e] = x0; a[e + 1] = x1;
            }
            float u0, u1;
            f2unpack(ss2, u0, u1);
            if (c0 + 16 <= cb) s0 += u0 + u1;
            else if (c0 >= cb && c0 + 16 <= nv) s1 += u0 + u1;
            else {
#pragma unroll
              for (int e = 0; e < 16; e++) {
                const int t = c0 + e;
                const float sq = a[e] * a[e];
                if (t < cb) s0 += sq;
                else if (t < nv) s1 += sq;
              }
            }
            float* hp = hcur + (size_t)k * 128 + c0;
#pragma unroll
            for (int q = 0; q < 4; q++) st_el4(hp + 4 * q, a[4 * q], a[4 * q + 1], a[4 * q + 2], a[4 * q + 3], pol);
          }
          tc_before();
          wbar();
          if (tid == 0) mbar_arrive(TFREE(buf));
          if (s0 != 0.f) atomicAdd(p.gsum + b0 * 512 + k, s0);
          if (s1 != 0.f) atomicAdd(p.gsum + (b0 + 1) * 512 + k, s1);
        }
        wbar();
        if (tid == 0) {
          __threadfence();
          red_release(g_ctr + 2 + b0, (unsigned)cb);
          if (nv > cb) red_release(g_ctr + 3 + b0, (unsigned)(nv - cb));
        }
        // ---- next x tile to L2 behind GEMM2
        if (t1 + G < p.ntiles) {
          const int tn0 = (t1 + G) * 128, nvn = min(128, p.N - tn0), tok = tid >> 2;
          if (tok < nvn) asm volatile("prefetch.global.L2 [%0];" ::"l"(p.x + (size_t)(tn0 + tok) * 128 + (tid & 3) * 32));
        }
      }
      if (has2) {
        int t0, nv, b0, cb;
        tile_geom(t2, p.N, p.HW, t0, nv, b0, cb);
        const bool two = nv > cb;
        if (tid == 0) {
          while (ld_acquire(g_ctr + 2 + b0) < (unsigned)p.HW) { }
          if (two) { while (ld_acquire(g_ctr + 3 + b0) < (unsigned)p.HW) { } }
        }
        wbar();
        // ---- GRN scale s = 1 + gw * G / (mean_k G + eps), per batch slot
#pragma unroll 1
        for (int sl = 0; sl < (two ? 2 : 1); sl++) {
          const float g = __fsqrt_rn(__ldcg(p.gsum + (b0 + sl) * 512 + tid));
          const float ws = warp_sum(g);
          if (lane == 0) s_red[warp] = ws;
          wbar();
          float tot = 0.f;
#pragma unroll
          for (int i = 0; i < NW; i++) tot += s_red[i];
          s_sc[sl * 512 + tid] = fmaf(s_gw[tid], __fdiv_rn(g, tot * (1.f / 512.f) + p.eps), 1.f);
          wbar();
        }
        if (!two) s_sc[512 + tid] = s_sc[tid];
        wbar();
        // ---- h' = h * s from the workspace, split hi/lo into two 32 KB MN-major B buffers (64 hidden rows each)
        const float* hprev = p.hws + ((size_t)(((r - 1) & 1) * G + cta) << 16);
#pragma unroll 1
        for (int kc = 0; kc < 8; kc++) {
          const int buf = kc & 1;
          if (kc < 2) {
            if (pend) { mbar_wait(XFREE, (uint32_t)((g1c - 1) & 1)); pend = false; }
          } else {
            mbar_wait(HFREE(buf), (uint32_t)(((kc >> 1) - 1) & 1));
          }
          float4 hv[2][2];
#pragma unroll
          for (int i = 0; i < 2; i++) {
            const int gi = tid + 512 * i, kr = gi >> 4, tg = gi & 15;
            const float4* src = reinterpret_cast<const float4*>(hprev + (size_t)(kc * 64 + kr) * 128 + tg * 8);
            hv[i][0] = __ldcg(src);
            hv[i][1] = __ldcg(src + 1);
          }
#pragma unroll
          for (int i = 0; i < 2; i++) {
            const int gi = tid + 512 * i, kr = gi >> 4, tg = gi & 15, k = kc * 64 + kr;
            const float sc0 = s_sc[k], sc1 = s_sc[512 + k];
            const float e[8] = {hv[i][0].x, hv[i][0].y, hv[i][0].z, hv[i][0].w, hv[i][1].x, hv[i][1].y, hv[i][1].z, hv[i][1].w};
            uint32_t hi[4], lo[4];
#pragma unroll
            for (int m = 0; m < 4; m++) {
              const int ta = tg * 8 + 2 * m;
              split2(e[2 * m] * (ta < cb ? sc0 : sc1), e[2 * m + 1] * (ta + 1 < cb ? sc0 : sc1), hi[m], lo[m]);
            }
            const int nc = tg >> 3, uu = tg & 7;
            unsigned char* d = sm + OFF_X + buf * 32768 + nc * 8192 + kr * 128 + ((uu ^ (kr & 7)) << 4);
            *reinterpret_cast<uint4*>(d) = make_uint4(hi[0], hi[1], hi[2], hi[3]);
            *reinterpret_cast<uint4*>(d + 16384) = make_uint4(lo[0], lo[1], lo[2], lo[3]);
          }
          fence_proxy_async();
          wbar();
          if (tid == 0) mbar_arrive(HFULL(buf));
        }
        // ---- out = (D2 main + D2 cross) + b2', lanes along output channels, one token per store instruction
        mbar_wait(G2DONE, (uint32_t)(g2c & 1));
        g2c++;
        tc_after();
        const int c = 32 * q4 + lane;
        const float bb = s_b2p[c];
#pragma unroll
        for (int hf = 0; hf < 2; hf++) {
          const int c0 = 32 * g4 + 16 * hf;
          float m[16], xc[16];
          tmem_ld16(tmem + ((uint32_t)(32 * q4) << 16) + (uint32_t)(256 + c0), m);
          tmem_ld16(tmem + ((uint32_t)(32 * q4) << 16) + (uint32_t)(384 + c0), xc);
          float* op = p.out + (size_t)(t0 + c0) * 128 + c;
#pragma unroll
          for (int e = 0; e < 16; e++)
            if (c0 + e < nv) op[(size_t)e * 128] = (m[e] + xc[e]) + bb;
        }
        tc_before();
        wbar();
        if (tid == 0) mbar_arrive(TFREE2);
      }
    }
  } else if (warp == NW) {
    // ---- MMA warp (uniform loop, elected issue)
    const uint32_t id = idesc_f16(128);
    int q = 0, g1c = 0, g2c = 0;
#pragma unroll 1
    for (int r = 0; r <= R; r++) {
      const bool has1 = r * G + cta < p.ntiles;
      const bool has2 = (r >= 1) && ((r - 1) * G + cta < p.ntiles);
      if (has1) {
        mbar_wait(XFULL, (uint32_t)(g1c & 1));
        tc_after();
#pragma unroll 1
        for (int hb = 0; hb < 4; hb++) {
          const int buf = hb & 1, use = 2 * g1c + (hb >> 1);
          mbar_wait(TFREE(buf), (uint32_t)((use & 1) ^ 1));
          tc_after();
          const uint32_t d = tmem + (uint32_t)(buf * 128);
#pragma unroll 1
          for (int kc = 0; kc < 2; kc++) {
            const int s = q & 3;
            mbar_wait(FULL(s), (uint32_t)((q >> 2) & 1));
            tc_after();
            const uint32_t wa = sb + OFF_W + s * 32768;
#pragma unroll
            for (int j = 0; j < 4; j++) {
              const uint64_t aH = sdesc(wa + j * 32, 16, 1024), aL = sdesc(wa + 16384 + j * 32, 16, 1024);
              const uint32_t bo = (uint32_t)((kc * 64 + j * 16) * 128);
              const uint64_t bH = sdesc(sb + OFF_X + bo, 16384, 1024), bL = sdesc(sb + OFF_X + 32768 + bo, 16384, 1024);
              mma_issue(d, aH, bH, id, (kc | j) ? 1u : 0u);
              mma_issue(d, aH, bL, id, 1u);
              mma_issue(d, aL, bH, id, 1u);
            }
            mma_commit(EMPTY(s));
            q++;
          }
          mma_commit(G1FULL(buf));
        }
        mma_commit(XFREE);
        g1c++;
      }
      if (has2) {
        mbar_wait(TFREE2, (uint32_t)((g2c & 1) ^ 1));
        tc_after();
        const uint32_t dm = tmem + 256u, dc = tmem + 384u;
#pragma unroll 1
        for (int kc = 0; kc < 8; kc++) {
          const int hbuf = kc & 1;
          mbar_wait(HFULL(hbuf), (uint32_t)((kc >> 1) & 1));
          tc_after();
          const int s = q & 3;
          mbar_wait(FULL(s), (uint32_t)((q >> 2) & 1));
          tc_after();
          const uint32_t wa = sb + OFF_W + s * 32768;
          const uint32_t hbase = sb + OFF_X + hbuf * 32768;
#pragma unroll
          for (int j = 0; j < 4; j++) {
            const uint64_t aH = sdesc(wa + j * 32, 16, 1024), aL = sdesc(wa + 16384 + j * 32, 16, 1024);
            const uint64_t bH = sdesc(hbase + j * 2048, 8192, 1024), bL = sdesc(hbase + 16384 + j * 2048, 8192, 1024);
            const uint32_t first = (kc | j) ? 1u : 0u;
            mma_issue(dm, aH, bH, id, first);
            mma_issue(dc, aH, bL, id, first);
            mma_issue(dc, aL, bH, id, 1u);
          }
          mma_commit(EMPTY(s));
          mma_commit(HFREE(hbuf));
          q++;
        }
        mma_commit(G2DONE);
        g2c++;
      }
    }
  } else {
    // ---- weight producer: 16 stages of 32 KB per tile (8 for GEMM1 of tile r, 8 for GEMM2 of tile r - 1)
    if (lane == 0) {
      while (ld_acquire(g_ctr) < (unsigned)G) { }
      asm volatile("fence.proxy.async;" ::: "memory");
      int q = 0;
#pragma unroll 1
      for (int r = 0; r <= R; r++) {
        const bool has1 = r * G + cta < p.ntiles;
        const bool has2 = (r >= 1) && ((r - 1) * G + cta < p.ntiles);
#pragma unroll 1
        for (int si = 0; si < 16; si++) {
          if ((si < 8 && !has1) || (si >= 8 && !has2)) continue;
          const int s = q & 3;
          mbar_wait(EMPTY(s), (uint32_t)(((q >> 2) & 1) ^ 1));
          mbar_expect(FULL(s), 32768u);
          bulk_g2s(sb + OFF_W + s * 32768, p.wimg + (size_t)si * 32768, 32768u, FULL(s));
          q++;
        }
      }
    }
    __syncwarp();
  }
  tc_before();
  __syncthreads();
  if (tid == 0) {
    const unsigned old = atomicAdd(g_ctr + 1, 1u);
    if (old == (unsigned)G - 1) {
      for (int b = 0; b < p.B; b++) atomicExch(g_ctr + 2 + b, 0u);
      atomicExch(g_ctr, 0u);
      __threadfence();
      atomicExch(g_ctr + 1, 0u);
    }
  }
  if (warp == NW) {
    tc_after();
    asm volatile("tcgen05.dealloc.cta_group::1.sync.aligned.b32 %0, %1;" ::"r"(tmem), "r"(512) : "memory");
  }
}

extern "C" const char* grn_launch(GParams p, void* stream) {
  static bool attr_set = false;
  cudaError_t e;
  if (!attr_set) {  // one maximal value for every shape
    e = cudaFuncSetAttribute(grn_mlp_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, SMEM_TOTAL);
    if (e != cudaSuccess) return cudaGetErrorString(e);
    attr_set = true;
  }
  if (p.B > 64 || p.HW <= 128) return "grn_launch: unsupported shape";
  void* args[] = {(void*)&p};
  e = cudaLaunchCooperativeKernel((const void*)grn_mlp_kernel, dim3(p.grid), dim3(NTH), args, (size_t)SMEM_TOTAL,
                                  (cudaStream_t)stream);
  if (e != cudaSuccess) return cudaGetErrorString(e);
  return nullptr;
}
