        int stage, r, k0;
        if (f < 16384) {
          w = __ldg(reinterpret_cast<const float4*>(p.w1) + f);
          const int n = f >> 5;
          k0 = (f & 31) * 4;
          stage = (n >> 7) * 2 + (k0 >> 6);
          r = n & 127;
        } else {
          const int g = f - 16384;
          w = __ldg(reinterpret_cast<const float4*>(p.w2) + g);
          r = g >> 7;
          k0 = (g & 127) * 4;
          stage = 8 + (k0 >> 6);
